#define MIN_VERSION 0x01000000     // 最小支持版本号 (1.0.0)
#define MAX_SEGMENT_COUNT 10       // 最大段数量

// 计算校验和的辅助函数
static unsigned int calculate_checksum(const unsigned char* data, int size) {
    unsigned int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += data[i];
    }
    return sum;
}

// 验证固件包头部信息
static int validate_header(const FirmwareHeader* header) {
    if (header->magic_number != FIRMWARE_MAGIC) {
        return -1; // 魔数不匹配
    }

    if (header->version < MIN_VERSION || header->version > MAX_VERSION) {
        return -2; // 版本号不在支持范围内
    }

    if (header->data_segments > MAX_SEGMENT_COUNT || header->data_segments == 0) {
        return -3; // 段数量无效
    }

    return 0; // 验证通过
}

int verify_firmware_package(const unsigned char* firmware_buffer, int package_size, unsigned int checksum, char* result_buffer, int result_size) {
    // 检查输入参数的有效性
    if (firmware_buffer == NULL || result_buffer == NULL || package_size <= 0 || result_size <= 0) {
        if (result_buffer && result_size > 0) {
            snprintf(result_buffer, result_size, "Error: Invalid input parameters");
        }
        return -1;
    }

    // 检查固件包大小是否足够包含头部信息
    if (package_size < sizeof(FirmwareHeader)) {
        snprintf(result_buffer, result_size, "Error: Firmware package too small to contain header");
        return -1;
    }

