    const FirmwareHeader* header = (const FirmwareHeader*)firmware_buffer;

    // 验证头部信息
    int header_result = validate_header(header);
    if (header_result != 0) {
        switch (header_result) {
            case -1:
                snprintf(result_buffer, result_size, "Error: Invalid firmware magic number");
                break;
            case -2:
                snprintf(result_buffer, result_size, "Error: Unsupported firmware version (0x%08X)", header->version);
                break;
            case -3:
                snprintf(result_buffer, result_size, "Error: Invalid segment count (%d)", header->data_segments);
                break;
            default:
                snprintf(result_buffer, result_size, "Error: Header validation failed");
                break;
