    // 检查固件包大小与头部中声明的大小是否一致
    if (header->total_size != package_size) {
        snprintf(result_buffer, result_size, "Error: Package size mismatch (header: %d, actual: %d)", 
                 header->total_size, package_size);
        return -4;
