// Helper function to create a valid firmware package
void create_valid_firmware(unsigned char* buffer, int size, unsigned int checksum) {
    if (size < 16) return;

    // Create a simple firmware header
    buffer[0] = 'F';  // Magic byte
    buffer[1] = 'W';  // Magic byte
    buffer[2] = 0x01; // Version
    buffer[3] = 0x00; // Reserved

    // Write size info
    *(int*)(buffer + 4) = size;
    *(unsigned int*)(buffer + 8) = checksum;

    // Fill the rest with pattern
    for (int i = 12; i < size; i++) {
        buffer[i] = (unsigned char)(i % 256);
    }
}

